using Clock=std::chrono::steady_clock;
constexpr uint64_t KiB=1024,LightBytes=511*511*2,OtherBytes=1024+16384+1024;
void Pump(){MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){Require(m.message!=WM_QUIT,"Lightmap window closed");TranslateMessage(&m);DispatchMessageW(&m);}std::this_thread::sleep_for(std::chrono::milliseconds(1));}
using Bytes=std::vector<uint8_t>;
Bytes Grid(uint16_t n=8192){Bytes p(LightBytes);for(size_t i=0;i<p.size();i+=2){p[i]=uint8_t(n);p[i+1]=uint8_t(n>>8);}return p;}
void Set(Bytes& p,unsigned x,unsigned y,uint16_t n){const auto i=(size_t(y)*511+x)*2;p[i]=uint8_t(n);p[i+1]=uint8_t(n>>8);}
uint16_t Get(const Bytes& p,unsigned x,unsigned y){const auto i=(size_t(y)*511+x)*2;return uint16_t(p[i]|unsigned(p[i+1])<<8);}
RuntimeAssetLease Publish(Device& d,RuntimeAssetKind kind,uint64_t id,uint64_t revision,uint32_t w,uint32_t h,const Bytes& bytes,uint64_t epoch=1,uint64_t generation=1){return d.PublishRuntimeAsset({epoch,id,generation,revision,kind},{w,h},std::make_shared<const Bytes>(bytes));}
void Geometry(RuntimeWorldFrame& p,const Bytes& bytes,unsigned origin=0){const auto vertex=[&](float x,float y,unsigned sx,unsigned sy){return EnhancedTerrainVertex{{x,y,0,1},0,0,float(Get(bytes,sx,sy))/16384.0f,float(sx),float(sy)};};auto a=vertex(-1,1,origin,origin),b=vertex(1,1,origin+64,origin),c=vertex(1,-1,origin+64,origin+64),e=vertex(-1,-1,origin,origin+64);p.terrain[0].vertices={a,b,c};p.terrain[1].vertices={a,c,e};}
void Revision(Device& d,RuntimeWorldFrame& p,const Bytes& bytes,uint64_t revision,unsigned origin=0,uint64_t generation=1){p.lightmap=Publish(d,RuntimeAssetKind::LightmapR16,3,revision,511,511,bytes,p.palette.Key().epoch,generation);Geometry(p,bytes,origin);}
RuntimeWorldFrame World(Device& d,const Bytes& bytes,uint64_t revision=1,uint64_t epoch=1,unsigned origin=0,uint64_t generation=1){RuntimeWorldFrame p;p.native_width=p.native_height=p.viewport_width=p.viewport_height=64;p.shade_settings={0,0,1,1,1,0,1,0,0};Bytes palette(1024,128);for(size_t i=3;i<palette.size();i+=4)palette[i]=255;p.palette=Publish(d,RuntimeAssetKind::PaletteRGBA8,1,1,256,1,palette,epoch);p.fade=Publish(d,RuntimeAssetKind::FadeR8,2,1,256,64,Bytes(16384),epoch);auto tile=Publish(d,RuntimeAssetKind::TileR8,10,1,32,32,Bytes(1024),epoch);p.terrain={{{},tile},{{},tile}};Revision(d,p,bytes,revision,origin,generation);return p;}
// Each screen centre samples four equally weighted R16 texels. Vertex shades
// are the vertex light divided by16384, so the interpolated correction cancels.
// RGB128 times sample/16384 is sum(four samples)/512; fixtures avoid half ties.
Image Expected(const Bytes& bytes,unsigned origin=0){Image p{64,64,Bytes(64*64*4)};for(unsigned y=0;y<64;++y)for(unsigned x=0;x<64;++x){const unsigned sx=origin+x,sy=origin+y;const unsigned sum=unsigned(Get(bytes,sx,sy))+Get(bytes,sx+1,sy)+Get(bytes,sx,sy+1)+Get(bytes,sx+1,sy+1);const auto c=uint8_t(std::min(128u,(sum+256)/512));const auto at=(y*64+x)*4;p.rgba[at]=p.rgba[at+1]=p.rgba[at+2]=c;p.rgba[at+3]=255;}return p;}
void Stats(std::ostream& o,const RuntimeResourceDiagnostics& s)
{
    o<<"{\"lightmapColdUploads\":"<<s.lightmap_cold_uploads<<",\"lightmapImageReuses\":"<<s.lightmap_image_reuses<<",\"lightmapIdenticalReuses\":"<<s.lightmap_identical_reuses<<",\"lightmapCopyRectangles\":"<<s.lightmap_copy_rectangles<<",\"lightmapUploadBytes\":"<<s.lightmap_upload_bytes<<",\"lightmapBboxFallbacks\":"<<s.lightmap_bbox_fallbacks<<",\"lightmapImages\":"<<s.lightmap_images<<",\"lightmapIdleImages\":"<<s.lightmap_idle_images<<",\"stagingAllocations\":"<<s.staging_allocations<<",\"stagingMaps\":"<<s.staging_maps<<",\"stagingReuses\":"<<s.staging_reuses
     <<",\"stagingGrowths\":"<<s.staging_growths<<",\"stagingTrimCount\":"<<s.staging_trim_count<<",\"stagingCapacityBytes\":"<<s.staging_capacity_bytes
     <<",\"stagingAllocationBytes\":"<<s.staging_allocation_bytes<<",\"stagingPools\":"<<s.staging_pools<<",\"resourceAllocations\":"<<s.resource_allocations
     <<",\"descriptorHeapAllocations\":"<<s.descriptor_heap_allocations<<",\"cpuHighWater\":"<<s.cpu_high_water<<",\"cpuBytes\":"<<s.cpu_bytes<<",\"defaultBytes\":"<<s.default_bytes
     <<",\"uploadBytes\":"<<s.upload_bytes<<",\"readbackBytes\":"<<s.readback_bytes<<",\"uploadHighWater\":"<<s.upload_high_water
     <<",\"descriptors\":"<<s.descriptors<<",\"worldPages\":"<<s.world_pages<<",\"worldRegions\":"<<s.world_regions
     <<",\"worldUploadBytes\":"<<s.world_upload_bytes<<",\"sourceUploadBytes\":"<<s.source_upload_bytes<<",\"paletteUploadBytes\":"<<s.palette_upload_bytes
     <<",\"alignedUploadBytes\":"<<s.aligned_upload_bytes<<",\"geometryUploadBytes\":"<<s.geometry_upload_bytes<<",\"submissions\":"<<s.submissions
     <<",\"presentations\":"<<s.presentations<<",\"heldSubmissions\":"<<s.held_submissions<<",\"pressureCollections\":"<<s.pressure_collections
     <<",\"pressureRecoveries\":"<<s.pressure_recoveries<<",\"wouldBlock\":"<<s.would_block<<",\"globalIdleCalls\":"<<s.global_idle_calls
     <<",\"fenceWaits\":"<<s.fence_waits<<",\"imageReadbacks\":"<<s.image_readbacks<<",\"readerHoldSlots\":"<<s.reader_hold_slots
     <<",\"failed\":"<<(s.failed?"true":"false")<<",\"quarantined\":"<<(s.quarantined?"true":"false")<<'}';
}
void TimingAggregate(std::ostream& o,const RuntimeTimingAggregate& a){o<<std::setprecision(17)<<"{\"samples\":"<<a.samples<<",\"totalMs\":"<<a.total_ms<<",\"latestMs\":"<<a.latest_ms<<",\"maximumMs\":"<<a.maximum_ms<<'}';}
void SparseTiming(std::ostream& o,const RuntimeTimingDiagnostics& t){o<<"{\"frequency\":"<<t.timestamp_frequency<<",\"pending\":"<<t.gpu_pending<<",\"completed\":"<<t.gpu_completed<<",\"cpuSubmission\":";TimingAggregate(o,t.world.normal.cpu_submitted);o<<",\"present\":";TimingAggregate(o,t.world.normal.cpu_present);o<<",\"gpuUploadRender\":";TimingAggregate(o,t.world.normal.gpu_upload_render);o<<'}';}
struct Runner {
    Device& d;std::filesystem::path output;RuntimeLightmapTestResult result;RuntimeResourceBudgets budgets;Diagnostics baseline;uint64_t isolated_submissions=0;
    std::vector<std::string> cases,comparisons,measurements,messages,timings;std::atomic<bool> watchdog{false};std::string active;
    Runner(Device& device,const std::filesystem::path& path):d(device),output(path),baseline(device.GetDiagnostics()){}
    void Check(bool value,const char* why){++result.checks;Require(value,why);}
    template<class E=std::runtime_error,class F>void Reject(F&& fn,const char* why){bool rejected=false;try{fn();}catch(const E&){rejected=true;}Check(rejected,why);}
    void Validation(){auto m=d.TakeValidationMessages();messages.insert(messages.end(),m.begin(),m.end());auto s=d.GetDiagnostics();Check(s.validation_errors==baseline.validation_errors&&s.validation_warnings==baseline.validation_warnings,"Lightmap GPU validation diagnostics");}
    void Bound(){auto s=d.GetRuntimeResourceDiagnostics();Check(s.cpu_bytes<=budgets.cpu_bytes&&s.default_bytes<=budgets.default_bytes&&s.upload_bytes<=budgets.upload_bytes&&s.readback_bytes<=budgets.readback_bytes&&s.descriptors<=budgets.descriptors&&s.staging_allocation_bytes<=s.upload_bytes&&s.staging_pools<=3,"Lightmap exceeded actual allocation bounds");}
    void Configure(uint32_t side=64,uint64_t upload=128*1024*KiB){d.ClearRuntimeResources();d.Resize(side,side);budgets={};budgets.upload_bytes=upload;d.ConfigureRuntimeResources(budgets);}
    void Case(const std::string& name,const std::function<void()>& body){active=name;Validation();try{body();Validation();++result.cases;cases.push_back("{\"name\":"+Json(name)+",\"passed\":true}");}catch(const std::exception& e){cases.push_back("{\"name\":"+Json(name)+",\"passed\":false,\"error\":"+Json(e.what())+"}");throw;}}
    void Record(const std::string& name,const RuntimeResourceDiagnostics& a,const RuntimeResourceDiagnostics& b){std::ostringstream o;o<<"{\"name\":"<<Json(name)<<",\"cpuByteCap\":"<<budgets.cpu_bytes<<",\"defaultByteCap\":"<<budgets.default_bytes<<",\"uploadByteCap\":"<<budgets.upload_bytes<<",\"before\":";Stats(o,a);o<<",\"after\":";Stats(o,b);o<<'}';measurements.push_back(o.str());}
    template<class P>RuntimeFrameTicket Submit(const P& p,bool diagnostic=false){const auto until=Clock::now()+std::chrono::seconds(25);for(;;){RuntimeSubmitResult s;if constexpr(std::is_same_v<P,RuntimeWorldFrame>)s=d.TrySubmitRuntimeWorldFrame(p,diagnostic);else s=d.TrySubmitRuntimeIndexedFrame(p,diagnostic);Bound();Check(p.palette.Valid(),"Lightmap consumed producer lease");if(s.status==RuntimeSubmitStatus::Submitted){++result.submitted_frames;Check(s.ticket.Valid()&&s.ticket.HasReadback()==diagnostic,"Lightmap ticket mismatch");return s.ticket;}Check(s.status==RuntimeSubmitStatus::WouldBlock&&!s.ticket.Valid(),"Unexpected staging submission status");Require(Clock::now()<until,"Lightmap submission remained blocked");d.CollectRuntimeResources();Pump();}}
    void Complete(RuntimeFrameTicket& t){const auto until=Clock::now()+std::chrono::seconds(25);while(!d.IsRuntimeFrameComplete(t)){Require(Clock::now()<until,"Lightmap completion timeout");Pump();}t.Reset();d.CollectRuntimeResources();}
    void Compare(RuntimeFrameTicket& t,const Image& expected,const std::string& name){Image image;const auto until=Clock::now()+std::chrono::seconds(25);while(!d.TryReadbackRuntimeFrame(t,image)){Require(Clock::now()<until,"Lightmap readback timeout");Pump();}auto diff=Differences(image,expected);auto stem="runtime-lightmap-"+name;Save(output/(stem+"-gpu"),image);Save(output/(stem+"-expected"),expected);result.rgba_byte_checks+=image.rgba.size();comparisons.push_back("{\"name\":"+Json(name)+",\"gpuStem\":"+Json(stem+"-gpu")+",\"expectedStem\":"+Json(stem+"-expected")+",\"width\":"+std::to_string(image.width)+",\"height\":"+std::to_string(image.height)+",\"rgbaBytes\":"+std::to_string(image.rgba.size())+",\"differingBytes\":"+std::to_string(diff)+"}");Validation();Check(diff==0,"Lightmap differs from independent analytic output");t.Reset();d.CollectRuntimeResources();}
    void NoWait(const RuntimeResourceDiagnostics& a){auto b=d.GetRuntimeResourceDiagnostics();Check(b.global_idle_calls==a.global_idle_calls&&b.fence_waits==a.fence_waits,"Lightmap inserted internal idle/wait");}
    void RecordTiming(const RuntimeTimingDiagnostics& a,const RuntimeTimingDiagnostics& b){std::ostringstream o;o<<"{\"name\":\"sparse100\",\"frames\":100,\"path\":\"world.normal\",\"scope\":\"CPU submission excludes private CPU publication and diagnostic pump/completion polling; Present is separate; GPU covers uploads/rendering only, not queue latency or copies/presentation\",\"liveFpsQualified\":false,\"performanceThresholdUsed\":false,\"before\":";SparseTiming(o,a);o<<",\"after\":";SparseTiming(o,b);o<<'}';timings.push_back(o.str());for(const auto* s:{&a.world.normal.cpu_submitted,&a.world.normal.cpu_present,&a.world.normal.gpu_upload_render,&b.world.normal.cpu_submitted,&b.world.normal.cpu_present,&b.world.normal.gpu_upload_render})Check(std::isfinite(s->total_ms)&&std::isfinite(s->maximum_ms)&&std::isfinite(s->latest_ms)&&s->total_ms>=0&&s->maximum_ms>=0&&s->latest_ms>=0,"Sparse lightmap timing is not finite/nonnegative");Check(a.timestamp_frequency>0&&b.timestamp_frequency==a.timestamp_frequency&&a.gpu_pending==0&&b.gpu_pending==0&&b.world.normal.cpu_submitted.samples==a.world.normal.cpu_submitted.samples+100&&b.world.normal.cpu_present.samples==a.world.normal.cpu_present.samples+100&&b.world.normal.gpu_upload_render.samples==a.world.normal.gpu_upload_render.samples+100&&b.gpu_completed==a.gpu_completed+100,"Sparse lightmap timing did not collect100 completed normal CPU/Present/GPU samples");}
    void Write(bool passed,const std::string& error,const RuntimeResourceDiagnostics& before){std::ofstream o(output/"runtime-lightmap-tests.json");o<<"{\"schema\":1,\"scope\":\"Three-image lightmap lineage reuse and dirty rectangles; independent analytic pixels and retained history accounting\",\"passed\":"<<(passed?"true":"false")<<",\"gate3Accepted\":false,\"readbackUsedAsInput\":false,\"frozenReferenceUsed\":false,\"liveProducerTested\":false,\"overlaysTested\":false,\"lensesTested\":false,\"dirtyLightmapRectanglesTested\":true,\"processDxgiBudgetTested\":false,\"gpuTimestampsTested\":true,\"defaultTextureRecyclingTested\":false,\"cpuPublicationCopiesEliminated\":false,\"checks\":"<<result.checks<<",\"casesPassed\":"<<result.cases<<",\"successfulSubmissions\":"<<result.submitted_frames<<",\"isolatedDeviceSubmissions\":"<<isolated_submissions<<",\"primaryDeviceSubmissions\":"<<(result.submitted_frames-isolated_submissions)<<",\"submissionCountScope\":\"All submissions use primary Device; measurements retain cumulative counters across Clear\",\"rgbaByteChecks\":"<<result.rgba_byte_checks<<",\"comparisonCount\":"<<comparisons.size()<<",\"rawFiles\":"<<comparisons.size()*2<<",\"bmpFiles\":"<<comparisons.size()*2<<",\"watchdogFired\":"<<(watchdog.load()?"true":"false")<<",\"error\":"<<Json(error)<<",\"activeCase\":"<<Json(active)<<",\"beforeCleanup\":";Stats(o,before);o<<",\"afterCleanup\":";Stats(o,d.GetRuntimeResourceDiagnostics());auto array=[&](const char* name,const std::vector<std::string>& values){o<<",\""<<name<<"\":[";for(size_t i=0;i<values.size();++i){if(i)o<<',';o<<values[i];}o<<']';};array("cases",cases);array("measurements",measurements);array("timings",timings);array("comparisons",comparisons);o<<",\"validationMessages\":[";for(size_t i=0;i<messages.size();++i){if(i)o<<',';o<<Json(messages[i]);}o<<"]}\n";Require(bool(o),"Cannot retain lightmap report");}
};
struct Hold {
    RuntimeReaderHold handle;std::jthread timer;std::atomic<bool>& fired;
    Hold(Device& d,std::atomic<bool>& f):fired(f){auto until=Clock::now()+std::chrono::seconds(25);while(!d.TryBeginRuntimeReaderHold(handle)){Require(Clock::now()<until,"Cannot arm staging hold");d.CollectRuntimeResources();Pump();}timer=std::jthread([this](std::stop_token stop){auto until=Clock::now()+std::chrono::seconds(15);while(!stop.stop_requested()){if(Clock::now()>=until){fired.store(true);handle.Release();}std::this_thread::sleep_for(std::chrono::milliseconds(10));}});}
    void Release(){bool ok=handle.Release();timer.request_stop();if(timer.joinable())timer.join();Require(ok&&!fired.load(),"Lightmap hold release/watchdog failure");}
    ~Hold(){timer.request_stop();if(timer.joinable())timer.join();handle.Release();}
};

